var W = 640, H = 420;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);
var g = draw.group();

var PLANE_X = 70, ROAD_Y = 380, Y_TOP = 60, X_MAX = 620, DA = 100;
var PHASE_NAMES = ['Reference line', 'Right triangles', 'Reveal distances'];
var state = { h: 115, ab: 150, phase: 0 };

function label(txt, x, y, anchor, size, color) {
  return g.text(txt).attr({
    x: x, y: y, 'text-anchor': anchor || 'middle', 'font-size': size || 13,
    'font-family': 'sans-serif', fill: color || '#222',
    'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round'
  });
}
function arcPath(cx, cy, R, theta) {
  var x0 = cx + R, y0 = cy;
  var x1 = cx + R * Math.cos(theta), y1 = cy + R * Math.sin(theta);
  return 'M ' + x0 + ' ' + y0 + ' A ' + R + ' ' + R + ' 0 0 1 ' + x1 + ' ' + y1;
}
function drawPlane(vx, vy) {
  var pg = g.group().translate(vx, vy);
  pg.polygon('-40,-3 -16,16 -27,16 -49,-1').fill('#8296ad').stroke('#5b6b80', 1);
  pg.path('M -72 -2 C -60 -8 -30 -9 -6 -6 L -2 -16 L 4 -15 L -1 -6 L 0 -2 L 0 2 C -30 5 -60 4 -72 -2 Z')
    .fill('#9db0c6').stroke('#5b6b80', 1);
  pg.line(-58, -3, -20, -3).stroke('#5b6b80', 0.8);
}

function draw() {
  g.clear();
  var h = state.h, ab = state.ab, dB = DA + ab;
  var vertSpace = ROAD_Y - Y_TOP;
  var s = Math.min(vertSpace / h, (X_MAX - PLANE_X) / dB);
  var vx = PLANE_X, vy = ROAD_Y - h * s;
  var Ax = PLANE_X + DA * s, Bx = PLANE_X + dB * s;
  var angA = Math.atan(h / DA), angB = Math.atan(h / dB);
  var degA = Math.round(angA * 180 / Math.PI), degB = Math.round(angB * 180 / Math.PI);

  // highway
  g.line(40, ROAD_Y, W - 20, ROAD_Y).stroke({ color: '#000', width: 2 });
