    // horizontal legs highlighted just above road
    g.line(vx, ROAD_Y - 7, Ax, ROAD_Y - 7).stroke({ color: '#c0392b', width: 2 });
    g.line(Ax, ROAD_Y - 7, Bx, ROAD_Y - 7).stroke({ color: '#2980b9', width: 2 });
    g.line(vx, ROAD_Y - 11, vx, ROAD_Y - 3).stroke('#c0392b', 1.4);
    g.line(Ax, ROAD_Y - 11, Ax, ROAD_Y - 3).stroke('#333', 1.4);
    g.line(Bx, ROAD_Y - 11, Bx, ROAD_Y - 3).stroke('#2980b9', 1.4);
  }

  // points A, B
  g.line(Ax, ROAD_Y - 5, Ax, ROAD_Y + 5).stroke('#000', 1.6);
  g.line(Bx, ROAD_Y - 5, Bx, ROAD_Y + 5).stroke('#000', 1.6);
  label('A', Ax, ROAD_Y + 20, 'middle', 15, '#000');
  label('B', Bx, ROAD_Y + 20, 'middle', 15, '#000');

  // angle arcs
  g.path(arcPath(vx, vy, 44, angB)).fill('none').stroke({ color: '#444', width: 1.3 });
  g.path(arcPath(vx, vy, 68, angA)).fill('none').stroke({ color: '#444', width: 1.3 });
  var mB = angB / 2, mA = (angA + angB) / 2;
  label(degB + '°', vx + 60 * Math.cos(mB), vy + 60 * Math.sin(mB) + 4, 'middle', 13, '#111');
  label(degA + '°', vx + 86 * Math.cos(mA), vy + 86 * Math.sin(mA) + 4, 'middle', 13, '#111');

  // airplane on top
