    label('h = ' + h, vx - 8, (vy + ROAD_Y) / 2, 'end', 12, '#333');
    var mAx = (vx + Ax) / 2, mAy = (vy + ROAD_Y) / 2;
    label('d₁ = ' + slA, mAx - 14, mAy - 6, 'end', 12, '#c0392b');
