</div>
<label>Airplane altitude: <output id="altitudeSliderVal">115</output>
  <input id="altitudeSliderInput" type="range" min="50" max="300" step="5" value="115" oninput="document.getElementById('altitudeSliderVal').value=this.value;update_altitudeSlider(+this.value)">
</label>
<label>Distance A–B: <output id="abDistanceSliderVal">150</output>
  <input id="abDistanceSliderInput" type="range" min="50" max="300" step="5" value="150" oninput="document.getElementById('abDistanceSliderVal').value=this.value;update_abDistanceSlider(+this.value)">
</label>
<button id="solvePhaseBtn" onclick="trigger_solvePhase()">Solve: Reference line</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 760, H = 430;
var svg = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);
var g = svg.group();

var VX = 140, ROAD_Y = 385, Y_TOP = 55, X_MAX = 745, DA = 100;
var PHASE_NAMES = ['Reference line', 'Right triangles', 'Reveal distances'];
var state = { h: 115, ab: 150, phase: 0 };

function label(txt, x, y, anchor, size, color) {
  return g.text(txt).attr({
    x: x, y: y, 'text-anchor': anchor || 'middle', 'font-size': size || 13,
    'font-family': 'sans-serif', fill: color || '#222',
    'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round'
  });
}
function arcPath(cx, cy, R, theta) {
  var x0 = cx + R, y0 = cy;
  var x1 = cx + R * Math.cos(theta), y1 = cy + R * Math.sin(theta);
  return 'M ' + x0 + ' ' + y0 + ' A ' + R + ' ' + R + ' 0 0 1 ' + x1 + ' ' + y1;
}
function drawPlane(vx, vy) {
  var pg = g.group().translate(vx, vy);
  pg.polygon('-46,-2 -20,15 -31,15 -55,-1').fill('#8296ad').stroke('#5b6b80', 1);
  pg.path('M -80 -2 C -66 -8 -34 -9 -8 -6 L -3 -16 L 3 -15 L -2 -6 L 0 -2 L 0 2 C -34 5 -66 4 -80 -2 Z')
    .fill('#9db0c6').stroke('#5b6b80', 1);
  pg.line(-64, -3, -22, -3).stroke('#5b6b80', 0.8);
  pg.css('cursor', 'pointer');
  pg.on('mousemove', function (e) { showTooltip('Airplane: vertex of both depression angles', e); });
  pg.on('mouseleave', hideTooltip);
  pg.on('click', function () { showPopup('Shared vertex', 'Both angles of depression are measured from this single point on the airplane, off the same horizontal reference. That is why the two sight-line triangles share one vertical altitude.'); });
}

function render() {
  g.clear();
  var h = state.h, ab = state.ab, dB = DA + ab;
  var s = Math.min((ROAD_Y - Y_TOP) / h, (X_MAX - VX) / dB);
  var vx = VX, vy = ROAD_Y - h * s;
  var Ax = VX + DA * s, Bx = VX + dB * s;
  var angA = Math.atan(h / DA), angB = Math.atan(h / dB);
  var degA = Math.round(angA * 180 / Math.PI), degB = Math.round(angB * 180 / Math.PI);

  // highway
  g.line(120, ROAD_Y, W - 15, ROAD_Y).stroke({ color: '#000', width: 2 });

  // horizontal reference (teal dashed)
  g.line(vx, vy, X_MAX, vy).stroke({ color: '#159a9a', width: 2, dasharray: '7,5' });

  // sight lines (gray dashed)
  g.line(vx, vy, Ax, ROAD_Y).stroke({ color: '#8a8a8a', width: 1.6, dasharray: '7,5' });
  g.line(vx, vy, Bx, ROAD_Y).stroke({ color: '#8a8a8a', width: 1.6, dasharray: '7,5' });

  // right-triangle construction
  if (state.phase >= 1) {
    g.line(vx, vy, vx, ROAD_Y).stroke({ color: '#333', width: 1.6 });
    g.path('M ' + vx + ' ' + (ROAD_Y - 12) + ' L ' + (vx + 12) + ' ' + (ROAD_Y - 12) + ' L ' + (vx + 12) + ' ' + ROAD_Y)
      .fill('none').stroke({ color: '#333', width: 1.2 });
    g.line(vx, ROAD_Y - 7, Ax, ROAD_Y - 7).stroke({ color: '#c0392b', width: 2 });
    g.line(Ax, ROAD_Y - 7, Bx, ROAD_Y - 7).stroke({ color: '#2980b9', width: 2 });
    g.line(vx, ROAD_Y - 12, vx, ROAD_Y - 2).stroke('#c0392b', 1.4);
    g.line(Ax, ROAD_Y - 12, Ax, ROAD_Y - 2).stroke('#333', 1.4);
    g.line(Bx, ROAD_Y - 12, Bx, ROAD_Y - 2).stroke('#2980b9', 1.4);
  }

  // points A, B markers + labels
  var mA = g.line(Ax, ROAD_Y - 6, Ax, ROAD_Y + 6).stroke('#000', 1.8);
  var mB = g.line(Bx, ROAD_Y - 6, Bx, ROAD_Y + 6).stroke('#000', 1.8);
  label('A', Ax, ROAD_Y + 22, 'middle', 16, '#000');
  label('B', Bx, ROAD_Y + 22, 'middle', 16, '#000');
  [mA, mB].forEach(function (mk, i) {
    mk.css('cursor', 'pointer');
    mk.on('mousemove', function (e) { showTooltip(i ? 'Point B: shallow depression angle' : 'Point A: steep depression angle', e); });
    mk.on('mouseleave', hideTooltip);
  });

  // angle arcs (inner = shallow to B, outer = steep to A)
  g.path(arcPath(vx, vy, 42, angB)).fill('none').stroke({ color: '#444', width: 1.3 });
  g.path(arcPath(vx, vy, 66, angA)).fill('none').stroke({ color: '#444', width: 1.3 });
  var mB2 = angB / 2, mA2 = (angA + angB) / 2;
  label(degB + '°', vx + 56 * Math.cos(mB2), vy + 56 * Math.sin(mB2) + 4, 'middle', 13, '#111');
  label(degA + '°', vx + 84 * Math.cos(mA2), vy + 84 * Math.sin(mA2) + 4, 'middle', 13, '#111');

  drawPlane(vx, vy);

  // revealed distances
  if (state.phase >= 2) {
    var slA = Math.round(Math.hypot(h, DA)), slB = Math.round(Math.hypot(h, dB));
    label('h = ' + h, vx - 8, (vy + ROAD_Y) / 2, 'end', 12, '#333');
    var mAx = (vx + Ax) / 2, mAy = (vy + ROAD_Y) / 2;
    label('d₁ = ' + slA, mAx - 16, mAy - 4, 'end', 12, '#c0392b');
    var mBx = (vx + Bx) / 2, mBy = (vy + ROAD_Y) / 2;
    label('d₂ = ' + slB, mBx + 4, mBy - 12, 'start', 12, '#2980b9');
    label('' + DA, (vx + Ax) / 2, ROAD_Y + 36, 'middle', 11, '#c0392b');
    label('' + ab, (Ax + Bx) / 2, ROAD_Y + 36, 'middle', 11, '#2980b9');
  }
}

function syncPhaseBtn() {
  document.getElementById('solvePhaseBtn').textContent = 'Solve: ' + PHASE_NAMES[state.phase];
}
function update_altitudeSlider(v) { state.h = v; render(); }
function update_abDistanceSlider(v) { state.ab = v; render(); }
function trigger_solvePhase() { state.phase = (state.phase + 1) % 3; syncPhaseBtn(); render(); }

var steps = [
  { n: 'The teal dashed line is the horizontal at flight altitude; each gray sight line opens downward from it, giving the 25° depression angle to B and the 49° depression angle to A from a single shared vertex.', phase: 0, h: 115, ab: 150 },
  { n: 'Dropping a perpendicular from the plane to the road splits the scene into two right triangles that share the same vertical altitude leg — the steep triangle to A and the shallow triangle to B.', phase: 1, h: 115, ab: 150 },
  { n: 'With the shared altitude linking the triangles, the tangent ratios give the horizontal distances and the sine ratios give the slant distances; drag the altitude or the A–B spacing to watch every labeled length and angle update consistently.', phase: 2, h: 115, ab: 150 }
];
var curStep = 0;
function applyStep(i) {
  curStep = i;
  var st = steps[i];
  state.phase = st.phase; state.h = st.h; state.ab = st.ab;
  document.getElementById('altitudeSliderInput').value = st.h;
  document.getElementById('altitudeSliderVal').value = st.h;
  document.getElementById('abDistanceSliderInput').value = st.ab;
  document.getElementById('abDistanceSliderVal').value = st.ab;
  document.getElementById('demoNarration').textContent = st.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (i + 1) + ' / ' + steps.length;
  syncPhaseBtn(); render();
}
function nextStep() { applyStep((curStep + 1) % steps.length); }
function prevStep() { applyStep((curStep - 1 + steps.length) % steps.length); }

render();
syncPhaseBtn();
window.__markRendered();
// @FIGURE_CODE_END

